    findViewById(R.id.bt_switch).setOnClickListener(new View.OnClickListener() {
        @Override
        public void onClick(View v) {
            index = index == 1 ? 0 :1;
            TrackManager.getInstance().initTrack(mInternalPlayer, index);
        }
